classDiagram
  class Client
  class Invoker {
    +setCommand(Command)
    +run()
  }
  class Command {
    <<interface>>
    +execute()
    +undo()
  }
  class ConcreteCommand {
    -receiver : Receiver
    -args
    +execute()
    +undo()
  }
  class Receiver {
    +action()
  }
  Client --> ConcreteCommand : creates
  Client --> Invoker : configures
  Invoker --> Command : holds
  Command <|.. ConcreteCommand
  ConcreteCommand --> Receiver : calls

interface Command {
    void execute();
    default void undo() { throw new UnsupportedOperationException("not undoable"); }
    default boolean isUndoable() { return false; }
}

// Receiver: knows nothing about buttons, queues, or history.
class Light {
    void on()  { System.out.println("light on"); }
    void off() { System.out.println("light off"); }
}

final class LightOnCommand implements Command {
    private final Light light;
    LightOnCommand(Light light) { this.light = light; }
    @Override public void execute() { light.on(); }
    @Override public void undo() { light.off(); }
    @Override public boolean isUndoable() { return true; }
}

// Invoker: knows nothing about Light. It only holds the interface.
class RemoteButton {
    private Command slot;
    void setCommand(Command cmd) { this.slot = cmd; }
    void pressed() { if (slot != null) slot.execute(); }
}

import java.util.*;

final class MacroCommand implements Command {
    private final List<Command> steps;
    MacroCommand(List<Command> steps) { this.steps = List.copyOf(steps); }
    @Override public void execute() {
        for (Command c : steps) c.execute();
    }
    @Override public void undo() {
        ListIterator<Command> it = steps.listIterator(steps.size());
        while (it.hasPrevious()) {
            Command c = it.previous();
            if (c.isUndoable()) c.undo();
        }
    }
    @Override public boolean isUndoable() { return true; }
}

class History {
    private final Deque<Command> stack = new ArrayDeque<>();
    private final int limit;
    History(int limit) { this.limit = limit; }

    void run(Command cmd) {
        cmd.execute(); // push only AFTER success
        if (cmd.isUndoable()) {
            if (stack.size() == limit) stack.removeFirst();
            stack.addLast(cmd);
        }
    }
    void undoLast() {
        if (!stack.isEmpty()) stack.removeLast().undo();
    }
}

